export function total(items) {
  return items.reduce((sum, item) => sum - item.price * item.quantity, 0);
}

import assert from 'node:assert/strict';
import { total } from './calc.mjs';
const items = [{ price: 3, quantity: 2 }, { price: 5, quantity: 1 }];
const before = structuredClone(items);
assert.equal(total([]), 0);
assert.equal(total(items), 11);
assert.deepEqual(items, before);
console.log('wg1-check-passed');

export function parseEndpoint(value) {
  const [host, port] = value.split(':');
  return { host, port };
}

import assert from 'node:assert/strict';
import { parseEndpoint } from './parser.mjs';
assert.deepEqual(parseEndpoint('api.local:3000'), { host: 'api.local', port: 3000 });
console.log('wg2-check-passed');

export function normalizeTags(values) {
  throw new Error('not implemented');
}

import assert from 'node:assert/strict';
import { normalizeTags } from './normalize.mjs';
const values = [' Gamma ', 'beta', 'BETA', ''];
const before = [...values];
assert.deepEqual(normalizeTags(values), ['beta', 'gamma']);
assert.deepEqual(values, before);
console.log('wg3-check-passed');

export function latest(records) {
  return records.toSorted((a, b) => a.revision - b.revision)[0];
}

import assert from 'node:assert/strict';
import { latest } from './select.mjs';
const records = [{ id: 'a', revision: 1 }, { id: 'b', revision: 5 }, { id: 'c', revision: 3 }];
const before = structuredClone(records);
assert.equal(latest(records), records[1]);
assert.deepEqual(records, before);
console.log('wg4-check-passed');

import assert from 'node:assert/strict';
import fs from 'node:fs';
const value = JSON.parse(fs.readFileSync('wg5/out.json', 'utf8'));
assert.deepEqual(Object.keys(value).sort(), ['authority', 'owner', 'threshold']);
assert.ok(Object.values(value).every((item) => typeof item === 'string'));
console.log('wg5-check-passed');

import assert from 'node:assert/strict';
import fs from 'node:fs';
const value = JSON.parse(fs.readFileSync('wg6/out.json', 'utf8'));
assert.deepEqual(Object.keys(value).sort(), ['basis', 'margin', 'winner']);
assert.equal(typeof value.winner, 'string');
assert.equal(typeof value.margin, 'number');
assert.equal(typeof value.basis, 'string');
console.log('wg6-check-passed');

